import { InsufficientStockError } from '../errors/DomainErrors';
import { Product } from '../product/Product';
import { Quantity } from '../shared/Quantity';

export interface StockAllocation {
  readonly product: Product;
  readonly quantity: Quantity;
}

/** Applies stock movements for a whole order across several products. */
export class StockReservationService {
  /** All-or-nothing: no product is touched unless every allocation can be satisfied. */
  reserve(allocations: readonly StockAllocation[]): void {
    for (const { product, quantity } of allocations) {
      if (!product.canReserve(quantity)) {
        throw new InsufficientStockError(product.id, quantity.value, product.available);
      }
    }
    for (const { product, quantity } of allocations) {
      product.reserve(quantity);
    }
  }

  release(allocations: readonly StockAllocation[]): void {
    for (const { product, quantity } of allocations) {
      product.release(quantity);
    }
  }

  commit(allocations: readonly StockAllocation[]): void {
    for (const { product, quantity } of allocations) {
      product.commit(quantity);
    }
  }
}

